	public FraudScenario getFraudScenario( FraudScenarioFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "FraudScenarioFetchOneSummary arg cannot be null" );

		FraudScenario entity = null;
		UUID id = summary.getFraudScenarioId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a FraudScenario using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


